package net.officefloor.hq.app.rollup;


/** Keeps the sheet's figures before the change, so {@link AuditRollup} can tell which moved. */
public class TakeRollup {
    public void take(@Val Sheet sheet, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SettingsRepository settings,
            Out<Rollup> rollupOut) {
        rollupOut.set(Rollup.of(sheet.id(), sheet.today(), people, claims, rates,
                settings.find(sheet.id())));
    }
}
package net.officefloor.hq.app.rollup;


/**
 * Records, after the change's own lines, the figures it moved: a ROLLUP line per person whose
 * claimed, due-total or overdue-total changed, then a TOTALS line when the sheet's totals changed. The sheet's
 * today is read again, as the change may have moved it.
 */
public class AuditRollup {
    public void audit(@Val Sheet sheet, @Val Rollup before, SheetRepository sheets, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SettingsRepository settings, HttpServletRequest request, Audit audit) {
        Rollup after = Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates,
                settings.find(sheet.id()));
        after.changesSince(before, sheet.id(), Audit.user(request)).forEach(audit::record);
    }
}

